}

fun igra(board: LongArray, index: Int): Long {
    var n = board[index]
    board[index] = 0
    if (n == 0L) return 0L

    val addToAll = n / 14
    n %= 14

    for (i in 0 until 14) {
        board[i] += addToAll
    }

    var currentIdx = index
    while (n > 0) {
        currentIdx = (currentIdx + 1) % 14
        board[currentIdx]++
        n--
    }

    var result = 0L
    for (i in 0 until 14) {
        if (board[i] % 2 == 0L) {
            result += board[i]
        }
    }
    return result
}

